AUTH_FEEDBACK_CATALOGS: dict[str, dict[str, str]] = {
    code: dict(zip(AUTH_FEEDBACK_KEYS, row.split("|"), strict=True))
    for code, row in AUTH_FEEDBACK_ROWS.items()
}

EXPECTED_AUTH_FEEDBACK_LOCALES = {
    code for code, _label in LANGUAGE_OPTIONS if code != "en"
} | {"ha"}

if set(AUTH_FEEDBACK_ROWS) != EXPECTED_AUTH_FEEDBACK_LOCALES:
    raise ValueError("Auth feedback catalog locale coverage is incomplete")

for _locale, _entries in AUTH_FEEDBACK_CATALOGS.items():
    if set(_entries) != set(AUTH_FEEDBACK_KEYS):
        raise ValueError(
            f"Auth feedback key coverage is incomplete for {_locale}"
        )
    if any(not value.strip() for value in _entries.values()):
        raise ValueError(
            f"Auth feedback contains an empty translation for {_locale}"
        )
    for _source, _translation in _entries.items():
        if sorted(re.findall(r"\{([^{}]+)\}", _source)) != sorted(
            re.findall(r"\{([^{}]+)\}", _translation)
        ):
            raise ValueError(
                f"Auth feedback placeholder mismatch for {_locale}"
            )
